input.sparql:
SELECT ?point ?class ?name WHERE {
  ?point a brick:ElectricPower .
  ?point rdfs:label ?name .
} LIMIT 50

SELECT DISTINCT ?class WHERE {
  ?p a ?class .
  FILTER (str(?class) =~ "lectric")
} LIMIT 80

SELECT ?point ?class ?tsid ?label WHERE {
  ?point a brick:Electric_Power_Sensor .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?point rdfs:label ?label }
}
